namespace ghidra.app.plugin.core.debug.gui.internal;

using ghidra.app.plugin;
using ghidra.app.plugin.core.debug;
using ghidra.app.plugin.core.debug.@event;
using ghidra.debug.api.tracemgr;
using ghidra.framework.plugintool;
